# integration_empirical_maturity ----
## Setup ----
data("data_big")
data_4_model <- FIMSFrame(data_big)
ages <- get_ages(data_4_model)
years <- get_start_year(data_4_model):get_end_year(data_4_model)

# The default logistic maturity has inflection_point = 2 and slope = 1.
logistic_maturity <- stats::plogis(ages - 2)

maturity_rows <- function(timing = NA_real_, observed = logistic_maturity) {
  tibble::tibble(
    type = "maturity_at_age",
    fleet = NA_character_,
    age = ages,
    length = NA_real_,
    timing = timing,
    observed = observed,
    unit = "proportion",
    uncertainty = NA_character_
  )
}

# Run the model at its initial values and return the estimates and objective.
run_at_initial_values <- function(data, parameters = NULL) {
  data_frame <- FIMSFrame(data)
  if (is.null(parameters)) {
    parameters <- suppressMessages(setup_default_parameters(data_frame))
  }
  fit <- parameters |>
    initialize_fims(data = data_frame) |>
    fit_fims(optimize = FALSE)
  output <- list(
    estimates = get_estimates(fit),
    objective = get_obj(fit)[["fn"]](get_obj(fit)[["par"]])
  )
  clear()
  output
}

get_by_year <- function(estimates, quantity) {
  estimates |>
    dplyr::filter(.data[["label"]] == quantity) |>
    dplyr::arrange(.data[["year_i"]]) |>
    dplyr::pull(.data[["estimated"]])
}

logistic_run <- run_at_initial_values(data_big)

## IO correctness ----
test_that("empirical maturity equal to the logistic ogive matches Logistic", {
  empirical_run <- run_at_initial_values(
    dplyr::bind_rows(data_big, maturity_rows())
  )

  #' @description Test that the empirical run used the Empirical maturity module.
  expect_true(
    any(empirical_run[["estimates"]][["label"]] == "maturity_at_age")
  )
  #' @description Test that proportion mature at age matches the logistic model.
  expect_equal(
    get_by_year(empirical_run[["estimates"]], "proportion_mature_at_age"),
    get_by_year(logistic_run[["estimates"]], "proportion_mature_at_age"),
    tolerance = 1e-8
  )
  #' @description Test that spawning biomass matches the logistic model.
  expect_equal(
    get_by_year(empirical_run[["estimates"]], "spawning_biomass"),
    get_by_year(logistic_run[["estimates"]], "spawning_biomass"),
    tolerance = 1e-8
  )
  #' @description Test that the objective function matches the logistic model.
  expect_equal(
    empirical_run[["objective"]],
    logistic_run[["objective"]],
    tolerance = 1e-8
  )
})

test_that("time-varying maturity scales spawning biomass in its year", {
  scale <- 0.5
  changed_year <- 10
  last_year_scale <- 0.8
  varying_run <- run_at_initial_values(dplyr::bind_rows(
    data_big,
    maturity_rows(),
    maturity_rows(
      timing = years[changed_year],
      observed = scale * logistic_maturity
    ),
    maturity_rows(
      timing = max(years),
      observed = last_year_scale * logistic_maturity
    )
  ))
  estimates <- varying_run[["estimates"]]

  #' @description Test that maturity_at_age output is labeled by year and age in the same order as the input.
  maturity_output <- estimates |>
    dplyr::filter(.data[["label"]] == "maturity_at_age") |>
    dplyr::filter(.data[["year_i"]] == changed_year) |>
    dplyr::arrange(.data[["age_i"]])
  # Module parameters are written to the output JSON with 6 significant digits.
  expect_equal(
    maturity_output[["estimated"]],
    scale * logistic_maturity,
    tolerance = 1e-5
  )

  #' @description Test that the year after the last model year uses the last year's maturity.
  proportion_mature <- estimates |>
    dplyr::filter(.data[["label"]] == "proportion_mature_at_age") |>
    dplyr::filter(.data[["year_i"]] == length(years) + 1) |>
    dplyr::arrange(.data[["age_i"]])
  expect_equal(
    proportion_mature[["estimated"]],
    last_year_scale * logistic_maturity,
    tolerance = 1e-8
  )

  spawning_biomass <- get_by_year(estimates, "spawning_biomass")
  logistic_spawning_biomass <- get_by_year(
    logistic_run[["estimates"]],
    "spawning_biomass"
  )

  #' @description Test that spawning biomass before the changed year is unchanged.
  expect_equal(
    spawning_biomass[seq_len(changed_year - 1)],
    logistic_spawning_biomass[seq_len(changed_year - 1)],
    tolerance = 1e-8
  )
  #' @description Test that spawning biomass in the changed year is scaled by the change in maturity.
  expect_equal(
    spawning_biomass[changed_year],
    scale * logistic_spawning_biomass[changed_year],
    tolerance = 1e-8
  )
  #' @description Test that the spawning biomass ratio in the changed year is scaled by the same amount.
  expect_equal(
    get_by_year(
      varying_run[["estimates"]],
      "spawning_biomass_ratio"
    )[changed_year],
    scale * get_by_year(
      logistic_run[["estimates"]],
      "spawning_biomass_ratio"
    )[changed_year],
    tolerance = 1e-8
  )
})

## Edge handling ----
test_that("initialize_maturity() works for a one-year model with year rows", {
  one_year <- dplyr::filter(
    data_big,
    is.na(timing) | timing <= years[1] |
      (type == "weight_at_age" & timing <= years[1] + 1)
  )
  data_one_year <- FIMSFrame(dplyr::bind_rows(
    one_year,
    maturity_rows(timing = years[1])
  ))
  parameters <- setup_default_Maturity(data_one_year, module_type = "Empirical")
  maturity <- initialize_maturity(parameters, data_one_year)

  #' @description Test that one year of year-specific rows gives one value per age.
  expect_equal(maturity$maturity_at_age$size(), length(ages))
  #' @description Test that the value for the first age is the input proportion mature.
  expect_equal(maturity$evaluate(min(ages)), logistic_maturity[1])
  clear()
})


test_that("retrospective runs work with year-specific maturity_at_age rows", {
  #' @description Skip the test unless explicitly enabled for heavy integration testing.
  testthat::skip_if_not(
    testthat:::env_var_is_true("RUN_SLOW_TESTS"),
    message = "Skipping: RUN_SLOW_TESTS is not set to true."
  )
  data_with_maturity <- dplyr::bind_rows(
    data_big,
    maturity_rows(),
    maturity_rows(timing = max(years), observed = 0.5 * logistic_maturity)
  )
  parameters <- suppressMessages(
    setup_default_parameters(FIMSFrame(data_with_maturity))
  )

  #' @description Test that a retrospective run with year-specific maturity_at_age rows completes.
  expect_no_error(
    fit <- run_modified_data_fims(
      years_to_remove = 1,
      data = data_with_maturity,
      parameters = parameters
    )
  )
  clear()
})

## Error handling ----
test_that("initialize_fims() errors for bad empirical maturity", {
  data_with_maturity <- FIMSFrame(
    dplyr::bind_rows(data_big, maturity_rows())
  )
  parameters <- suppressMessages(setup_default_parameters(data_with_maturity))
  is_maturity <- parameters[["label"]] %in% "maturity_at_age"

  #' @description Test that an estimated empirical maturity value returns an error.
  estimated <- parameters
  estimated[["estimation_type"]][which(is_maturity)[1]] <- "fixed_effects"
  expect_error(
    initialize_fims(parameters = estimated, data = data_with_maturity),
    "constant"
  )
  clear()

  #' @description Test that a value above 1 returns an error.
  above_one <- parameters
  above_one[["value"]][which(is_maturity)[1]] <- 1.5
  expect_error(
    initialize_fims(parameters = above_one, data = data_with_maturity),
    "between 0 and 1"
  )
  clear()

  #' @description Test that zero maturity at every age in a year returns an error.
  all_zero <- parameters
  all_zero[["value"]][is_maturity] <- 0
  expect_error(
    initialize_fims(parameters = all_zero, data = data_with_maturity),
    "0 at every age"
  )
  clear()

  #' @description Test that a missing age returns an error.
  missing_age <- parameters[-which(is_maturity)[1], ]
  expect_error(
    initialize_fims(parameters = missing_age, data = data_with_maturity),
    "one .*maturity_at_age.* value per age"
  )
  clear()
})
